package com.hbm.client.oilplant;
import com.hbm.block.oilplant.*;import com.hbm.hazard.HbmHazards;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.item.ItemProperties;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.level.GrassColor;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.fml.event.lifecycle.FMLClientSetupEvent;import net.neoforged.neoforge.client.event.RegisterColorHandlersEvent;
/** Source fixed3x3 foliage average and inventory GrassColor(.5,1), independent of modern blend-radius setting. */
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
public final class OilBotanyClient {
 private static boolean tinted(net.minecraft.world.level.block.state.BlockState state){int meta=state.getValue(OilFlowerBlock.META);return state.getBlock() instanceof OilTallPlantBlock?meta==0||meta==8:meta==1||meta==3;}
 @SubscribeEvent public static void blocks(RegisterColorHandlersEvent.Block e){e.register((state,level,pos,index)->{if(!tinted(state))return -1;var world=Minecraft.getInstance().level;if(world==null||pos==null)return GrassColor.get(.5,1);int r=0,g=0,b=0;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){int color=world.getBiome(pos.offset(x,0,z)).value().getFoliageColor();r+=color>>16&255;g+=color>>8&255;b+=color&255;}return(r/9&255)<<16|(g/9&255)<<8|b/9&255;},OilBotanyContent.FLOWER.get(),OilBotanyContent.TALL.get());}
 @SubscribeEvent public static void items(RegisterColorHandlersEvent.Item e){e.register((stack,index)->{var item=(OilPlantItem)stack.getItem();int meta=item.metadata(stack);boolean tall=item.getBlock() instanceof OilTallPlantBlock;return 0xff000000|((tall?meta==0:meta==1||meta==3)?GrassColor.get(.5,1):-1);},OilBotanyContent.FLOWER_ITEM.get(),OilBotanyContent.TALL_ITEM.get());}
 @SubscribeEvent public static void setup(FMLClientSetupEvent e){e.enqueueWork(()->{for(var item:java.util.List.of(OilBotanyContent.FLOWER_ITEM.get(),OilBotanyContent.TALL_ITEM.get()))ItemProperties.register(item,ResourceLocation.parse("hbm:legacy_metadata"),(stack,level,entity,seed)->((OilPlantItem)stack.getItem()).metadata(stack));ItemProperties.register(OilBotanyContent.MATERIAL.get(),ResourceLocation.parse("hbm:legacy_metadata"),(stack,level,entity,seed)->OilBotanyContent.MATERIAL.get().ordinal(stack));});}
}
